echo -e "${RESET}"
echo -e "${BOLD}${ORANGE}         OCode Installer${RESET}"
echo ""

PREBUILT_BIN="$SCRIPT_DIR/bin/ocode"
if [ -f "$PREBUILT_BIN" ]; then
    MODE="prebuilt"
elif [ -n "$_OCODE_BLOB" ]; then
    MODE="source"
    if command -v g++ &> /dev/null; then
        CXX="g++"
    elif command -v clang++ &> /dev/null; then
        CXX="clang++"
    else
        echo -e "${RED}[ERROR]${RESET} No C++ compiler found. Please install one:"
        echo ""
        echo -e "  ${YELLOW}FreeBSD:${RESET}   sudo pkg install gcc   (or: sudo pkg install llvm)"
        echo -e "  ${YELLOW}OpenBSD:${RESET}   doas pkg_add gcc       (or: doas pkg_add llvm)"
        echo -e "  ${YELLOW}NetBSD:${RESET}    sudo pkgin install gcc"
        echo -e "  ${YELLOW}DragonFly:${RESET} sudo pkg install gcc"
        echo ""
        exit 1
    fi
    echo -e "${GREEN}[✓]${RESET} $CXX found: $($CXX --version | head -1)"
else
    echo -e "${RED}[ERROR]${RESET} No binary or embedded source found. Re-download the OCode release and try again."
    exit 1
fi
echo ""

echo -e "${BOLD}Where do you want to install OCode?${RESET}"
echo ""
echo -e "  ${CYAN}[1]${RESET} /usr/local/bin   (system-wide, needs sudo)"
echo -e "  ${CYAN}[2]${RESET} ~/.local/bin     (current user only, no sudo)"
echo -e "  ${CYAN}[3]${RESET} Custom path"
echo ""
read -p "  Choice [1]: " choice
choice=${choice:-1}

case $choice in
    1)
        INSTALL_DIR="/usr/local/bin"
        DOC_DIR="/usr/local/share/ocode"
        USE_SUDO=true
        ;;
    2)
        INSTALL_DIR="$HOME/.local/bin"
        DOC_DIR="$HOME/.local/share/ocode"
        USE_SUDO=false
        mkdir -p "$INSTALL_DIR"
        ;;
    3)
        read -p "  Enter path: " INSTALL_DIR
        DOC_DIR="$INSTALL_DIR/docs"
        USE_SUDO=false
        mkdir -p "$INSTALL_DIR"
        ;;
    *)
        INSTALL_DIR="/usr/local/bin"
        DOC_DIR="/usr/local/share/ocode"
        USE_SUDO=true
        ;;
esac

echo ""

if [ "$MODE" = "prebuilt" ]; then
    echo -e "${BOLD}Using bundled binary...${RESET}"
    BUILT_BIN="$PREBUILT_BIN"
    echo -e "${GREEN}[✓]${RESET} Found bin/ocode"
else
    echo -e "${BOLD}Building OCode...${RESET}"
    BUILD_DIR="$(mktemp -d)"
    trap 'rm -rf "$BUILD_DIR"' EXIT

    echo "$_OCODE_BLOB" | base64 -d > "$BUILD_DIR/ocode.cpp"
    if $CXX -std=c++17 -O2 -s -o "$BUILD_DIR/ocode" "$BUILD_DIR/ocode.cpp" -lssl -lcrypto -lsqlite3 -lpthread 2>/dev/null; then
        echo -e "${GREEN}[✓]${RESET} Build successful (with OpenSSL + SQLite3 — full feature set)"
    else
        echo -e "${YELLOW}[!]${RESET} Full build failed — trying without OpenSSL..."
        if $CXX -std=c++17 -O2 -s -DOCODE_NO_OPENSSL -o "$BUILD_DIR/ocode" "$BUILD_DIR/ocode.cpp" -lsqlite3 -lpthread 2>/dev/null; then
            echo -e "${GREEN}[✓]${RESET} Build successful (no HTTPS, but SQLite3 + threading enabled)"
        else
            echo -e "${YELLOW}[!]${RESET} SQLite3 link failed — building with minimal feature set"
            $CXX -std=c++17 -O2 -s -DOCODE_NO_OPENSSL -DOCODE_NO_SQLITE -o "$BUILD_DIR/ocode" "$BUILD_DIR/ocode.cpp" -lpthread
            echo -e "${GREEN}[✓]${RESET} Build successful (minimal — no HTTPS, no SQLite, no threading)"
        fi
    fi
    BUILT_BIN="$BUILD_DIR/ocode"
fi
echo ""

echo -e "${BOLD}Installing to ${CYAN}$INSTALL_DIR/ocode${RESET}..."
if [ "$USE_SUDO" = true ]; then
    sudo install -m 755 "$BUILT_BIN" "$INSTALL_DIR/ocode"
else
    install -m 755 "$BUILT_BIN" "$INSTALL_DIR/ocode"
fi
echo -e "${GREEN}[✓]${RESET} Installed!"

echo -e "${BOLD}Installing ocd (package manager)...${RESET}"
if [ "$USE_SUDO" = true ]; then
    sudo ln -sf "$INSTALL_DIR/ocode" "$INSTALL_DIR/ocd"
else
    ln -sf "$INSTALL_DIR/ocode" "$INSTALL_DIR/ocd"
fi
echo -e "${GREEN}[✓]${RESET} ocd installed (symlink to ocode)"
echo ""

echo -e "${BOLD}Installing documentation to ${CYAN}$DOC_DIR${RESET}..."
if [ "$USE_SUDO" = true ]; then
    sudo mkdir -p "$DOC_DIR"
    if [ -f "$SCRIPT_DIR/README.md" ]; then
        sudo cp "$SCRIPT_DIR/README.md" "$DOC_DIR/README.md"
    elif [ -n "$_README_BLOB" ]; then
        echo "$_README_BLOB" | base64 -d | sudo tee "$DOC_DIR/README.md" > /dev/null
    fi
    if [ -f "$SCRIPT_DIR/LICENSE" ]; then
        sudo cp "$SCRIPT_DIR/LICENSE" "$DOC_DIR/LICENSE"
    elif [ -n "$_LICENSE_BLOB" ]; then
        echo "$_LICENSE_BLOB" | base64 -d | sudo tee "$DOC_DIR/LICENSE" > /dev/null
    fi
    if [ -d "$SCRIPT_DIR/examples" ]; then
        sudo cp -r "$SCRIPT_DIR/examples" "$DOC_DIR/examples"
    fi
else
    mkdir -p "$DOC_DIR"
    if [ -f "$SCRIPT_DIR/README.md" ]; then
        cp "$SCRIPT_DIR/README.md" "$DOC_DIR/README.md"
    elif [ -n "$_README_BLOB" ]; then
        echo "$_README_BLOB" | base64 -d > "$DOC_DIR/README.md"
    fi
    if [ -f "$SCRIPT_DIR/LICENSE" ]; then
        cp "$SCRIPT_DIR/LICENSE" "$DOC_DIR/LICENSE"
    elif [ -n "$_LICENSE_BLOB" ]; then
        echo "$_LICENSE_BLOB" | base64 -d > "$DOC_DIR/LICENSE"
    fi
    if [ -d "$SCRIPT_DIR/examples" ]; then
        cp -r "$SCRIPT_DIR/examples" "$DOC_DIR/examples"
    fi
fi
echo -e "${GREEN}[✓]${RESET} Docs installed (README.md + LICENSE extracted)"
echo ""

if [[ ":$PATH:" != *":$INSTALL_DIR:"* ]]; then
    echo -e "${YELLOW}[!]${RESET} $INSTALL_DIR is not on your PATH."
    echo -e "    Add this to your ~/.bashrc or ~/.zshrc:"
    echo ""
    echo -e "    ${CYAN}export PATH=\"$INSTALL_DIR:\$PATH\"${RESET}"
    echo ""
    echo -e "    Then run: ${CYAN}source ~/.bashrc${RESET}"
    echo ""
fi

echo -e "${BOLD}${GREEN}Done!${RESET}"
echo -e "  Run OCode:      ${CYAN}ocode <file.oc>${RESET}"
echo -e "  Package manager: ${CYAN}ocd install <file.oc>${RESET}"
echo -e "  Documentation: see ${CYAN}README.md${RESET} in ${CYAN}$DOC_DIR${RESET}"
echo ""
